  NF>=6 {n++; if ("'$6=="NA" || $6=="") na++; else if (($6+0)<0.05) sig++; if ($6!="NA" && $6!="" && (($6+0)<min || minset==0)) {min=$6+0; minset=1}; if ($6!="NA" && $6!="" && (($6+0)>max || maxset==0)) {max=$6+0; maxset=1}}
  END {printf "rows=%d'"\\nNA_padj=%d\\nnonNA_padj=%d\\npadj_lt_0.05=%d\\nmin_nonNA=%g\\nmax_nonNA=%g\\n\",n,na,n-na,sig,min,max}
' codex_tmp/deseq2_result.tabular
awk -F '\\t' 'NF<6 {print NR \": NF=\" NF \": \" "'$0}'"' codex_tmp/deseq2_result.tabular | head"
